function hospitalClosedOn(hid, ds){ var h = HOSPITAL_DATA[hid]; if(!h) return false; var sp = hospitalSpecial(hid, ds); if(sp) return sp.mode==='closed'; return closedWholeDay(h.closedRules, new Date(ds+'T00:00:00').getDay()); }
