  var m0 = /^指定(\d\d:\d\d)-(\d\d:\d\d)$/.exec(part||''); if(m0) return [m0[1], m0[2]]; /* CMD-1014-02：OFF 改成「全天 / 指定时间」，part 写成 指定09:00-13:00 */
