/* 01 / 02 的旧五个部位 → 新部位（旧数据兜底显示 + 迁移 48 共用） */
var CONCERN_OLD_KEY = {eyes:'f_eyes', nose:'f_nose', mouth:'f_mouth', face:'f_all', body:'b_all'};
var CONCERN_PHOTO_SPEC = '白底，1200×1600px';
function cesc(x){ return String(x==null ? '' : x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;'); }
function concernPartDef(key){
  var k0 = CONCERN_OLD_KEY[key] || key;
  return CONCERN_PARTS.filter(function(p){ return p.key===k0; })[0] || {key:key, group:'', label:(key==='legacy' ? '未分部位' : key), angles:[]};
}
function concernGroupOf(x){ var d = concernPartDef(x.part); return d.group || ''; }
function concernCid(x){ return x.part+(x.sub ? '|'+x.sub : ''); }
function concernCardTitle(x){ var d = concernPartDef(x.part), sub = x.sub && d.subs ? (CONCERN_SUBS[d.subs].filter(function(s){ return s.key===x.sub; })[0]||{}).label : ''; return d.label+(sub ? ' · '+sub : ''); }
function concernPvCat(c){ return (c && (c.revisitEval || isRevisitConsult(c))) ? '复诊' : '面诊'; }
function concernCardFull(x){ var g = (CONCERN_GROUPS.filter(function(y){ return y.key===concernGroupOf(x); })[0]||{}).label; return (g ? g+' · ' : '')+concernCardTitle(x); }
function concernSortKey(x){ var d = concernPartDef(x.part), i = CONCERN_PARTS.indexOf(d), si = d.subs ? CONCERN_SUBS[d.subs].findIndex(function(s){ return s.key===x.sub; }) : 0; return i*10+Math.max(0, si); }
/* 旧案件（没有 concerns）：合成一张「未分部位」卡片；迁移 47 / 48 会把存档里的旧案件真正转成新结构 */
function concernCards(c){
  if(Array.isArray(c.concerns) && c.concerns.length) return c.concerns;
  if(c.concern || c.expectation || c.photoUploaded || c.videoUploaded) return [{part:'legacy', desc:c.concern||'', expect:c.expectation||'', video:c.videoUploaded ? {name:'视频（旧资料）'} : null, photos:c.photoUploaded ? {legacy:{name:'照片（旧资料）'}} : {}, legacy:true}];
  return [];
}
function concernSync(c){
  var cards = c.concerns || [];
  c.concern = cards.map(function(x){ return concernCardFull(x)+'：'+(x.desc||''); }).join('；');
  c.expectation = cards.map(function(x){ return concernCardFull(x)+'：'+(x.expect||''); }).join('；'); /* 汇总文字：给 KR 基础资料 / 韩文摘要等旧读法用（希望预期现在记在每张部位卡片里，CMD-1019-04） */
  c.photoUploaded = cards.some(function(x){ return Object.keys(x.photos||{}).length>0; });
  c.videoUploaded = cards.some(function(x){ return !!x.video; });
}
/* CMD-1021-17：客人在预约页手写的苦恼（c.visitNote，只读参考）；「不面诊」时苦恼 = 메타뷰 + 手写文字框（c.concernText，没改过就默认带入预约页手写的内容） */
function guestConcernText(c){ return String(c.visitNote||'').trim(); }
function concernTextOf(c){ return c.concernText!==undefined && c.concernText!==null ? c.concernText : guestConcernText(c); }
function saveConcernText(v){ var c = getCurrentCase(); if(!c) return; c.concernText = v; c.materialsError = ''; }
function guestConcernRowHtml(c){
  var t = guestConcernText(c); if(!t) return '';
  return '<div class="case-field-row" style="align-items:flex-start;"><span class="fk">客人手写的苦恼</span><div style="flex-grow:1;font-size:13px;white-space:pre-wrap;">'+cesc(t)+' <span style="font-size:12px;color:var(--muted);">（预约页填写，仅供参考）</span></div></div>';
}

/* ===== CMD-1021-18 术后 / 复诊来访流程（IN）=====
   触发：到店后弹「是否关联之前案件？」选了案件，或一般来访在「关联之前案件」选了案件 → c.followup = true（不再走一般的基础资料路线）。
   「基本信息」默认折叠；面诊需求二选一：需要院长面诊（复诊：从关联案件做过的项目里选，院长沿用原案件、面诊费照免除原因「复诊」）/ 不面诊（메타뷰 / 苦恼选填 + 术后恢复照片卡选填）；
   不面诊之后进本地管理，分「术后管理（关联案件的印尼术后管理）/ 本地管理」两类。选「不关联」走 17 的一般流程。 */
function followupOn(c){ return !!(c && c.followup && c.linkedCase && c.linkedCase.caseId); }
function followSrcById(id){ return CASE_ITEMS.filter(function(x){ return x.id===id; })[0]; }
function followSrc(c){ return (c && c.linkedCase && c.linkedCase.caseId) ? CASE_ITEMS.filter(function(x){ return x.id===c.linkedCase.caseId; })[0] : null; }
/* 关联案件做过的项目（赴韩已完成项目 + 本院买过并用过的本地项目；一个都没有就列没取消的赴韩项目） */
function followDoneItems(src){
  var out = [], seen = {}, add = function(n){ if(n && !seen[n]){ seen[n] = 1; out.push(n); } };
  if(!src) return out;
  krAllItems(src).filter(function(it){ return it.done && !it.cancelled && !it.swapped && !krIsMgmtItemC(it); }).forEach(function(it){ add(it.name); }); /* CMD-1022-19：只列原案件做过的赴韩施术项目（本地项目、管理项目、术后管理都不列） */
  return out;
}
function followItemPart(name){ var p = PROJECT_LIBRARY.filter(function(x){ return x.name===name && Array.isArray(x.parts) && x.parts.length; })[0], ps = projectPartsOf(p || {name:name}); return partBase(ps[0] || 'f_all'); }
function toggleBasicOpen(){ var c = getCurrentCase(); if(!c) return; c.basicOpen = !c.basicOpen; renderCaseBody(c); }
/* CMD-1021-21：复诊每勾一个要看的项目就出现该项目的视频 + 各角度照片上传卡（c.revisitMedia = [{name, part, video, photos}]，角度读项目对应部位的配置，同 18 的术后恢复卡） */
function revisitMediaOf(c, name){ return (c.revisitMedia||[]).filter(function(x){ return x.name===name; })[0]; }
