    logCaseEvent(c, actingName(), '到店：使用之前购买的项目——新的独立案件'+(c.boughtFrom.length ? '，来自 '+c.boughtFrom.join('、')+' 购买' : '')+'（不加入原主案件，原主案件状态不变）'); buildCaseLog(c); renderCaseSubtitle(c); renderCaseBody(c);
