  var specLabel = String(rawName||'').split(' · ')[1], sp = specLabel ? (p.specs||[]).filter(function(s){ return s.label===specLabel; })[0] : null, mn = sp && parseInt(sp.dirMin,10) > 0 ? parseInt(sp.dirMin,10) : (parseInt(p.dirMin,10) || 30);
