    if(!isUpgraded(m)) return;
    if(dayNoLegacy(m)){ m.dayNoOn = false; return; }
    m.dayNoOn = true; m.dayNos = m.dayNos||{}; m.dayNoSeq = m.dayNoSeq||0;
