  c.krJudge.refundKind = kind;
  logCaseEvent(c, by, 'KR判断：不能施术，定金'+(kind==='all' ? '全部退回' : '不退')+'（请 IN 室长按此判断操作）');
  pushNotif('赴韩施术','KR 判断不能施术、定金'+(kind==='all' ? '全部退回' : '不退')+'：'+c.name+'，请按此操作', {caseId:c.id});
