/* 种子里写死的系统时间点（Timeline dt、通知 ts、创建/激活时间…）原来是"诊所当地时间"，现在系统事件时间点存 UTC：种子生成完后一次性换算成 UTC，Timeline 等在雅加达显示就不会多 7 小时（2026-10-08，CMD-1007-04） */
function seedSurgerySubs(){ CASE_ITEMS.forEach(function(c){ if(c.settlementDone && c.subItems && c.subItems.length) syncSurgerySub(c); }); } /* 已有在韩 timeline 的演示案件：补上自动产生的「施术」一行 */
/* 演示：等待报告的案件补上面诊时间和院长日程里的面诊块（面诊时间 = 预计出报告时间 − 30 分钟；排不进去的跳过）——CMD-1008-12 C1 */
function seedConsultBlocks(){
  CASE_ITEMS.forEach(function(c){
    if(c.consultStatus!=='awaiting_report' || !c.director || !c.reportEta || c.consultAt) return;
    var hid = caseKrHospital(c), hr = hospitalHours(hid), e = fmtUtc(c.reportEta, KR_TZ).split(' '), m = timeToMin(e[1]) - 30;
    if(m < timeToMin(hr.open)) m = timeToMin(hr.open);
    if(m > timeToMin(hr.close)-30) m = timeToMin(hr.close)-30;
    var time = minToTime(m);
    if(krSurgerySlotError(hid, c.director, e[0], time, 30, c.clinicId+':'+c.id, {exceptKind:'面诊'})) return;
    c.consultAt = {date:e[0], time:time}; syncConsultBlock(c);
  });
}
function seedTimesToUtc(root, tz){
  var seen = [], SEED_TIME_KEYS = {dt:1, ts:1, time:1, at:1, addedAt:1, uploadedAt:1, editedAt:1, doneAt:1, informedAt:1, updatedAt:1, createdAt:1, activatedAt:1, reportEta:1}; /* 变量放函数里：这个函数在文件前面就会被调用 */
  (function walk(o){
    if(!o || typeof o!=='object' || seen.indexOf(o)>-1) return; seen.push(o);
    if(Array.isArray(o)){ o.forEach(walk); return; }
    Object.keys(o).forEach(function(k){
      var v = o[k];
      if(SEED_TIME_KEYS[k] && typeof v==='string' && /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(v)) o[k] = localToUtc(v.slice(0,10), v.slice(11), tz);
      else if(v && typeof v==='object') walk(v);
    });
  })(root);
}
function buildClinicSeed(cid){
  var vars = emptyClinicVars(cid), saved = {}, keepClinic = CURRENT_CLINIC_ID, keepSeeding = SEEDING, keepActor = SEED_ACTOR, keepIn = IN_COORDINATORS.slice();
  CLINIC_VAR_NAMES.forEach(function(n){ saved[n] = window[n]; window[n] = vars[n]; });
  CURRENT_CLINIC_ID = cid; SEEDING = true; SEED_ACTOR = (clinicAccounts(cid).filter(function(a){ return a.role==='manager' && a.name; })[0] || {name:'A1 室长'}).name;
  var out = {};
  try{ syncInCoordinators(); seedClinicDemo(cid); seedFixVisits(); seedSnapshotConsultFee(); seedResolveOverlaps(); seedTimesToUtc([CASE_ITEMS, CLIENTS, NOTIFS, SMS_LOG, CHAT_DATA], clinicTzOf(CLINIC_SETTINGS)); seedConsultBlocks(); seedSurgerySubs(); }catch(e){ console.error('[种子] '+cid, e); }
  CLINIC_VAR_NAMES.forEach(function(n){ out[n] = window[n]; });
  CLINIC_VAR_NAMES.forEach(function(n){ window[n] = saved[n]; });
  CURRENT_CLINIC_ID = keepClinic; SEEDING = keepSeeding; SEED_ACTOR = keepActor;
  IN_COORDINATORS.length = 0; Array.prototype.push.apply(IN_COORDINATORS, keepIn);
  return out;
}


/* KR 的本地管理项目库（CMD-1012-04）：每家医院一份清单（韩元），KR 项目库页面「本地管理项目」组；缺的补上 */
/* CMD-1021-02 演示数据：几个项目设成「院长操作」，规格间院长时间有的一样有的不一样（热玛吉 300发 30 / 600发 45 / 眼部 450发 45；ONDA 各规格 30）。只在项目从没设过（dirOp 为 undefined）时补，用户改过的不动 */
/* CMD-1021-08：管理项目的「第一次使用（术后第 N 天开始）」和「建议间隔」存在项目库里（KR 项目库管理项目编辑页）：
   项目层 firstNa / firstMode('all'|'spec') / firstAll、intNa / intMode / intAll；规格层 sp.firstDay / sp.interval（各规格分别设定时用）。
   null = 无关。只是建议：预约时带出建议日期，实际预约可以随意改。 */
function mgFirstOf(p, sp){ if(!p || p.firstNa) return null; var v = parseInt(p.firstMode==='spec' ? (sp ? sp.firstDay : '') : p.firstAll, 10); return isNaN(v) || v<0 ? null : v; }
function mgIntervalOf(p, sp){ if(!p || p.intNa) return null; var v = parseInt(p.intMode==='spec' ? (sp ? sp.interval : '') : p.intAll, 10); return isNaN(v) || v<1 ? null : v; }
/* 项目库里的规格 → 项目条目上的 firstDay / interval / intNa（付款后条目自带，不再回头读项目库） */
function mgSchedOf(p, sp, total){ var f = mgFirstOf(p, sp), iv = mgIntervalOf(p, sp); return {firstDay:f===null ? '' : f, interval:(total>1 && iv!==null) ? iv : 0, intNa:iv===null}; }
var DEMO_MGSCHED = {'ONDA 提升':{first:{all:14}, int:{all:14}}, '热玛吉':{first:{na:true}, int:{spec:{'300发':180, '600发':240, '眼部 225发':180, '眼部 450发':240}}}, '钛提升':{first:{all:7}, int:{na:true}}};
var DEMO_DIROP = {'热玛吉':{min:30, specs:{'300发':30, '600发':45, '眼部 225发':30, '眼部 450发':45}}, 'ONDA 提升':{min:30, specs:{}}};
function krLocalLib(hid){ var h = HOSPITAL_DATA[hid]; if(!h) return []; if(!h.localLib){ h.localLib = buildLocalProjects('KR', hid); gmcStamp(h.localLib); }
  if(!h._mgDemo){ h._mgDemo = 1; h.localLib.forEach(function(p){ if(p.firstMode!==undefined || p.firstNa!==undefined || p.intMode!==undefined || p.intNa!==undefined) return; var df = DEMO_MGSCHED[p.name] || {first:{all:7}, int:{all:7}};
    if(df.first.na) p.firstNa = true; else { p.firstNa = false; p.firstMode = 'all'; p.firstAll = df.first.all; }
    if(df.int.na) p.intNa = true; else if(df.int.spec){ p.intNa = false; p.intMode = 'spec'; (p.specs||[]).forEach(function(sp){ sp.interval = df.int.spec[sp.label] || 180; }); } else { p.intNa = false; p.intMode = 'all'; p.intAll = df.int.all; } }); }
  if(!h._dirDemo){ h._dirDemo = 1; h.localLib.forEach(function(p){ var df = DEMO_DIROP[p.name]; if(df && p.dirOp===undefined){ p.dirOp = true; p.dirMin = df.min; (p.specs||[]).forEach(function(sp){ if(df.specs[sp.label]) sp.dirMin = df.specs[sp.label]; }); } }); }
  return h.localLib; }
/* 选择 / 新增时用的管理项目清单：不含非活性化的（按 id / 名字查已有项目仍用 krLocalLib） */
function krLocalLibOn(hid){ return krLocalLib(hid).filter(function(p){ return p.active!==false; }); }
Object.keys(HOSPITAL_DATA).forEach(function(h){ krLocalLib(h); });

/* 演示案件标记（CMD-1012-06 补）：种子里建立的案件都带 demo:true；用户自己新建的案件（id 为 r+时间戳）没有这个标记，测试覆盖页只计算后者。
   旧存档里没有标记的演示案件，按 id 补上（用户新建的案件 id 一律是 r 加 9 位以上数字）。 */
function markDemoCases(){ try{ (CASE_ITEMS||[]).forEach(function(c){ if(c.demo===undefined) c.demo = !/^r\d{9,}/.test(String(c.id)); }); }catch(e){} }
(CASE_ITEMS||[]).forEach(function(c){ c.demo = true; }); /* 种子刚建立的案件：全部明确标记为演示（含种子里用 createReservationCase 生成的预约案件）；存档读入后用户新建的案件没有这个标记 */


/* CMD-1015-05 七：打印「赴韩施术计划」——院长面诊内容（印尼文翻译版，用现有演示翻译文字）+ 推荐项目整理 + 确定的赴韩项目内容 + 印尼室长备注；不印任何金额 */
/* CMD-1019-15：赴韩施术计划打印 = 给客人带去韩国的（不写金额，先只中文）：抬头 / 1 行程概要 / 2 施术项目 / 3 日程表 / 4 术前准备 / 5 日程确认与变动 / 6 备注 */
function printPlanDate(ds, n){ var t0 = new Date(ds+'T00:00:00'); t0.setDate(t0.getDate()+n); return t0.getFullYear()+'-'+pad2(t0.getMonth()+1)+'-'+pad2(t0.getDate()); }
/* 日程表：施术、术后管理（已预约用预约时间，没预约 = 施术日 + 第 N 天）、管理项目（第一次使用 + 间隔）；按日期排 */
function printPlanSchedule(c){
  var ks = c.krSchedule || {}, base = ks.confirmedDate || '', rows = [], items = krActiveItems(c), surg = items.filter(function(it){ return !krIsMgmtItemC(it); });
  if(base) rows.push({d:base, t:ks.confirmedTime||'', what:'施术：'+(surg.map(function(it){ return it.name; }).join('、') || '—'), place:'韩国'});
  /* 术后管理：已预约的行用预约时间；其余按所需术后管理（第 N 天，多次按间隔）排建议日期 */
  var booked = (c.subItems||[]).filter(function(s){ return s.kind==='术后管理记录' && !s.skipped && s.date; }), usedBk = {};
  surg.forEach(function(it){ (it.postcare||[]).forEach(function(x){
    var days = pcDays(x), nm = pcLabel(x); if(!days.length) days = [0];
    days.forEach(function(dy, k){
      var b = booked.filter(function(s){ return !usedBk[s.id] && s.projectName===it.name && String(s.content||'').indexOf(nm)===0; })[0];
      if(b){ usedBk[b.id] = 1; rows.push({d:b.date, t:b.time||'', what:'术后管理：'+nm+'（'+it.name+'）', place:b.place==='IN' ? '印尼' : '韩国', booked:true}); }
      else if(base && dy){ rows.push({d:printPlanDate(base, dy), t:'', what:'术后管理：'+nm+'（'+it.name+'）', place:x.place==='KR' ? '韩国' : '韩国或印尼（以预约为准）'}); }
    });
  }); });
  items.filter(krIsMgmtItemC).forEach(function(it){
    var total = Math.max(1, it.qty||1), itv = total>1 ? (it.interval||1) : 0, na0 = !!it.intNa, f0 = (it.firstDay===undefined || it.firstDay==='' || it.firstDay===null) ? null : Number(it.firstDay);
    if(!base || f0===null) return;
    var bkd = (c.subItems||[]).filter(function(x){ return rowOwnedBy(it, x) && !x.skipped && x.date; }).length; /* CMD-1020-04：已预约的次数用预约时间（下面单独列），建议日期只列没预约的 */
    for(var k = bkd; k < total; k++) if(k===0 || !na0) rows.push({d:printPlanDate(base, f0 + k*itv), t:'', what:'管理项目：'+it.name+(total>1 ? '（第 '+(k+1)+'/'+total+' 次）' : ''), place:'韩国'});
  });
  /* CMD-1020-04：KR 在韩预约的施术项目 / 管理项目到院（预约使用）也列进日程表 */
  (c.subItems||[]).filter(function(x){ return !x.skipped && x.date && (x.surgUse || x.holdUseOf); }).forEach(function(x){ rows.push({d:x.date, t:x.time||'', what:(x.surgUse ? '施术：'+x.surgUse : '管理项目：'+x.holdUseOf), place:'韩国', booked:true}); });
  rows.sort(function(a, b){ return (a.d+' '+(a.t||'99:99')).localeCompare(b.d+' '+(b.t||'99:99')); });
  return rows;
}
/* 施术项目的施术日（CMD-1019-21）：到院后另外加的施术在那次到院（visitKey = 地点|日期）；预约使用的施术看它的预约行；其余 = 主施术日。显示时推算，不另存 */
function itemSurgDate(c, it){
  var ks = c.krSchedule || {};
  if(it && it.visitKey){ var d = String(it.visitKey).split('|')[1]; if(d) return d; }
  var vr = (c.subItems||[]).filter(function(s){ return s.kind==='增加项目' && s.visitKey && !s.skipped && it && (s.projectName===it.name || String(s.content||'').indexOf(it.name)>-1); })[0];
  if(vr){ var d2 = String(vr.visitKey).split('|')[1] || vr.date; if(d2) return d2; }
  var nm = it && it.name, hit = (c.subItems||[]).filter(function(s){ return s.surgUse && !s.skipped && s.date && nm && String(s.content||'').indexOf(nm)>-1; })[0];
  if(hit) return hit.date;
  return ks.confirmedDate || '';
}
/* 术后管理标「（对应施术 · 术后第 N 天）」：从它对应的施术的施术日算起（施术日 = 第 0 天），显示时推算、不另存，施术日改期自动重算（CMD-1019-21 二） */
function careDayText(c, projName, date){
  if(!projName || !date) return '';
  var it = (c.procedureItems||[]).filter(function(x){ return x.name===projName; })[0], sd = it ? itemSurgDate(c, it) : ((c.krSchedule||{}).confirmedDate || '');
  if(!sd) return ''; var n = ymdDiff(sd, date); return n>=0 ? '术后第 '+n+' 天' : '';
}
function careDayTag(c, s){
  if(!s || s.kind!=='术后管理记录' || !s.projectName) return '';
  var t = careDayText(c, s.projectName, s.date); return t ? ' <span style="font-size:12px;color:var(--muted);font-weight:400;">（'+String(s.projectName).replace(/&/g,'&amp;').replace(/</g,'&lt;')+' · '+t+'）</span>' : '';
}
/* CMD-1020-06：到院卡 / Timeline 里一行项目的统一写法 = 名称 + 一行灰字（三端一致）
   施术：只写名称；术后管理：名称 + 灰字「对应施术 · 术后第 N 天」；管理项目：名称 + 灰字「剩 N / 共 M 次」；
   地点另有一栏、名称里不写「在韩国」；不写「（预约）」「（持有项目使用）」这类来源后缀 */
function visitRowType(c, s){
  if(s.kind==='施术' || s.surgUse) return '施术';
  if(s.holdUseOf) return '管理项目';
  if(s.kind==='增加项目'){ var it = (c.procedureItems||[]).filter(function(x){ return x.name===s.projectName; })[0]; return (it && (it.mgmtPlan || isLocalKrItem(it) || it.service)) ? '管理项目' : '施术'; }
  return '术后管理';
}
function visitRowLabel(c, s){
  var type = visitRowType(c, s), clean = function(t){ return String(t||'').replace(/（(预约|持有项目使用)）/g, '').replace(/^施术：/, ''); }, name = '', sub = '';
  if(type==='施术'){ name = s._item || s.surgUse || (s.kind==='增加项目' ? s.projectName : '') || clean(s.content); }
  else if(type==='管理项目'){
    var base = s.holdUseOf || s.projectName || clean(s.content), it = s.holdIid ? (itemByKey(c, s.holdIid) || (c.procedureItems||[]).filter(function(x){ return x.name===base; })[0]) : (c.procedureItems||[]).filter(function(x){ return x.name===base; })[0];
    name = buyName(base)+((s.useQty||1)>1 ? ' ×'+s.useQty : ''); if(it){ var tot = it.qty || 1; sub = '剩 '+Math.max(0, holdItemLeft(c, it))+' / 共 '+tot+' 次'; }
  } else {
    var e = careEntryOfRow(c, s); name = e ? (e.x.name || e.x.mgmt) : clean(s.content).replace(/（.*$/, '');
    var dt = s.projectName ? careDayText(c, s.projectName, s.date) : ''; sub = [s.projectName ? buyName(s.projectName) : '', dt].filter(Boolean).join(' · ');
  }
  return {type:type, name:name, sub:sub};
}
/* CMD-1022-14：Timeline 里术后管理一行写出对应施术（例「颧骨缩小 · 术后复诊检查」）；施术 / 管理项目只写名称 */
function rowLogName(c, s){ var l = visitRowLabel(c, s); return (l.type==='术后管理' && s.projectName) ? buyName(s.projectName)+' · '+l.name : l.name; }
function visitRowLabelHtml(c, s){
  var l = visitRowLabel(c, s), e = function(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;'); };
  return e(l.name)+(l.sub ? '<div style="font-size:12px;color:var(--muted);font-weight:400;">'+e(l.sub)+'</div>' : '');
}
/* Timeline 记录的阶段标签按项目类型：施术 / 术后管理 / 管理项目 */
function rowStageLabel(c, s){ return visitRowType(c, s); }
function printKrPlan(){
  var c = getCurrentCase(); if(!c) return; var e = function(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;'); };
  var items = krActiveItems(c), ks = c.krSchedule || {}, cl = clientByName(c.name), hid = c.hospitalId || clinicHospital(CURRENT_CLINIC_ID), en = hospitalEn(hid);
  var surg = items.filter(function(it){ return !krIsMgmtItemC(it); }), mg = items.filter(krIsMgmtItemC), coord = actingName();
  var fill = function(t){ return smsFill(t, {coordinator:coord, phone:CLINIC_SETTINGS.phone}); };
  var lines = function(t){ return String(t||'').split('\n').filter(function(x){ return x.trim(); }); };
  /* 1 行程概要 */
  var local = ks.confirmedDate ? krToClinic(ks.confirmedDate, ks.confirmedTime||'00:00') : null;
  var stayP = stayPlanOf(surg, ks.confirmedDate||'', function(it){ return itemSurgDate(c, it); }); /* CMD-1019-17：建议在韩天数 = 各施术项目最大值，最早回国日 = 施术日 + 天数，写原因 */
  var sum = [];
  sum.push(['到院日期时间', ks.confirmedDate ? e(ks.confirmedDate+' '+(ks.confirmedTime||'')+'（韩国时间）')+(local && ks.confirmedTime ? ' ／ '+e(local.date+' '+local.time)+'（印尼时间）' : '') : '（施术日期还没确认）']);
  sum.push(['医院', e(en.name)]); sum.push(['到院地址', e(ks.address || en.address)]);
  if(stayText(c)) sum.push(['在韩期间', e(stayText(c).replace(/ ～ /, ' ～ '))+(c.stay && c.stay.in && c.stay.out ? '（入境日 ～ 离境日）' : '')]);
  sum.push(['建议在韩停留', stayP.days ? e(stayLineText(stayP).replace(/^建议在韩停留 /, '')) : '—']);
  /* 2 施术项目：施术写麻醉方式，管理项目写 N 份（共 M 次） */
  var itemRows = surg.map(function(it){ return '<tr><td>'+e(it.name)+'</td><td>'+(it.anesthesia ? '麻醉：'+e(it.anesthesia.label||'')+(anesFastOf(it.anesthesia) ? '（需空腹 '+anesFastOf(it.anesthesia)+' 小时）' : '') : '')+'</td></tr>'; }).concat(mg.map(function(it){ return '<tr><td>'+e(it.name)+'（管理项目）</td><td>'+e(mgmtQtyText(it))+'</td></tr>'; })).join('');
  /* 3 日程表 */
  var sch = printPlanSchedule(c).map(function(r){ return '<tr><td style="white-space:nowrap;">'+e(r.d)+(r.t ? ' '+e(r.t) : '')+'</td><td>'+e(r.what)+'</td><td>'+e(r.place)+'</td></tr>'; }).join('');
  /* 4 术前准备 */
  var fasts = surg.map(function(it){ return {n:it.name, h:anesFastOf(it.anesthesia)}; }).filter(function(x){ return x.h; }), prep = [];
  if(fasts.length) prep = prep.concat(fasts.length===1 ? ['麻醉需空腹：'+e(fasts[0].n)+'，施术前 '+fasts[0].h+' 小时内禁止食用任何食物和饮品'] : fasts.map(function(x){ return '麻醉需空腹：'+e(x.n)+'，施术前 '+x.h+' 小时内禁止食用任何食物和饮品'; }));
  var pa = passportAlert(c), pp = '携带护照'+(pa.level==='ok' ? '（有效至 '+e(passportOf(cl).expiry)+'）' : '');
  prep.push(pa.level==='expired' || pa.level==='before' || pa.level==='none' ? '<b style="color:#c00;">⚠ 携带护照：'+e(pa.level==='none' ? '护照未登记，请尽快提供' : pa.text)+'</b>' : pp);
  prep = prep.concat(lines(CLINIC_SETTINGS.printPrep!==undefined ? CLINIC_SETTINGS.printPrep : PRINT_PREP_DEFAULT).map(e));
  var tpl = CLINIC_SETTINGS.printConfirm!==undefined ? CLINIC_SETTINGS.printConfirm : PRINT_CONFIRM_DEFAULT;
  var html = '<html><head><meta charset="utf-8"><title>赴韩施术计划</title><style>body{font-family:sans-serif;padding:28px;color:#222;line-height:1.7;font-size:14px;} h1{font-size:22px;margin:0 0 4px;} h2{font-size:15px;margin:22px 0 8px;border-bottom:2px solid #333;padding-bottom:4px;} table{border-collapse:collapse;width:100%;} td,th{border:1px solid #ccc;padding:6px 10px;text-align:left;font-size:13px;vertical-align:top;} th{background:#f4f1ec;} ul{margin:4px 0;padding-left:20px;} .k{color:#555;width:110px;}</style></head><body>'+
    '<h1>赴韩施术计划</h1><div style="font-size:13px;color:#444;">客人：'+e(c.name)+'　·　Case ID：'+e(c.caseNo||'')+'　·　'+e(CLINIC_SETTINGS.name)+'<br>负责室长：'+e(coord)+'　联系方式：'+e(CLINIC_SETTINGS.phone)+'</div>'+
    '<h2>1　行程概要</h2><table>'+sum.map(function(r){ return '<tr><td class="k">'+r[0]+'</td><td>'+r[1]+'</td></tr>'; }).join('')+'</table>'+
    '<h2>2　施术项目</h2>'+(itemRows ? '<table>'+itemRows+'</table>' : '<div>（暂无）</div>')+
    '<h2>3　日程表</h2>'+(sch ? '<table><tr><th>日期</th><th>内容</th><th>地点</th></tr>'+sch+'</table>' : '<div>（施术日期确认后生成）</div>')+'<div style="font-size:12px;color:#666;margin-top:4px;">以上为建议日期，以医院实际安排为准。</div>'+
    '<h2>4　术前准备</h2><ul>'+prep.map(function(x){ return '<li>'+x+'</li>'; }).join('')+'</ul>'+
    '<h2>5　日程确认与变动</h2>'+lines(fill(tpl)).map(function(x){ return '<div>'+e(x)+'</div>'; }).join('')+
    '<h2>6　备注</h2><div style="white-space:pre-wrap;">'+(c.recInNote ? e(c.recInNote) : '—')+'</div>'+
    '</body></html>';
  /* CMD-1015-15：先预览，点［确认打印］后才打印（顶部工具条打印时不会印出来） */
  html = html.replace('<body', '<body').replace('</style>', '@media print{.pv-bar{display:none !important;}} .pv-bar{position:sticky;top:0;background:#fff7ec;border-bottom:1px solid #e5d3b8;padding:10px 28px;margin:-28px -28px 18px;display:flex;gap:10px;align-items:center;font-size:13px;} .pv-bar button{padding:7px 16px;border-radius:6px;border:1px solid #9A6A4B;background:#9A6A4B;color:#fff;cursor:pointer;} .pv-bar button.o{background:#fff;color:#9A6A4B;}</style>');
  html = html.replace(/<body([^>]*)>/, '<body$1><div class="pv-bar"><span style="flex:1;">打印预览：确认内容没问题后再打印</span><button onclick="window.print()">确认打印</button><button class="o" onclick="window.close()">关闭</button></div>');
  var w = window.open('', '_blank'); if(!w){ alert('浏览器拦截了预览窗口，请允许弹出窗口后重试'); return; }
  w.document.write(html); w.document.close();
}

/* ============ CMD-1015-20 项目卡三分页：术后管理 / 施术 / 管理项目的「单元」与 本次使用 / 预约 ============ */
function krIsMgmtItemC(it){ return !!(it.mgmtPlan || it.service || isLocalKrItem(it)); }
/* 术后管理单元：已有的行（含取消本次后退回的 skipped）+ 还没预约的名额（按施术项目的「所需术后管理」次数算） */
/* CMD-1025-01 九：付清尾款后才能预约术后管理（KR 约韩国的、IN 约印尼的都一样）；客人还没到店，不知道会不会做、也还没付尾款，没必要先约。已结案的案件不受限 */
function careBookBlock(c){ return (c && !c.krBalancePaid && !isEnded(c)) ? '付清尾款后才能预约' : ''; }
function careBookBtn(c, label, code, style){ var blk = careBookBlock(c); return blk ? '<button class="btn-outline" disabled title="'+blk+'" style="'+style+'opacity:.45;cursor:not-allowed;">'+label+'</button>' : '<button class="btn-outline" style="'+style+'" onclick="'+code+'">'+label+'</button>'; }
function careUnits(c){
  var rows = careRows(c).filter(function(s){ return !s.surgUse; }), pool = rows.filter(function(s){ return !s.projectName; }), res = {rows:[], unbooked:[]};
  var items = krActiveItems(c).filter(function(it){ return !krIsMgmtItemC(it); });
  items.forEach(function(it){
    var mine = rows.filter(function(s){ return s.projectName===it.name; }), slots = [];
    (it.postcare||[]).forEach(function(x, i){ for(var k = 0; k < (x.times||1); k++) slots.push({it:it, x:x, i:i, k:k}); });
    while(mine.length < slots.length && pool.length) mine.push(pool.shift());
    mine.forEach(function(s){ res.rows.push({s:s, item:it.name}); });
    /* 已有的行按内容对上它属于哪一条所需术后管理（对不上的才占第一个空名额），剩下的才是未预约（CMD-1015-28） */
    var left = slots.slice();
    mine.forEach(function(s){ var k = -1; left.forEach(function(sl, n){ if(k<0 && (sl.x.mgmt||sl.x.name) && String(s.content||'').indexOf(sl.x.mgmt||sl.x.name)===0) k = n; }); left.splice(k<0 ? 0 : k, 1); });
    left.forEach(function(sl){ res.unbooked.push({item:it.name, it:it, x:sl.x, i:sl.i, k:sl.k}); });
  });
  pool.forEach(function(s){ res.rows.push({s:s, item:''}); });
  return res;
}
/* CMD-1020-18：同一条所需术后管理有多次名额时，每一次一个独立的预约 key（第 0 次沿用旧 key，旧预约不受影响）；建议日期按这一次是第几次算 */
function careUnitKey(u){ var b = 'unit|'+u.item+'|'+u.i; return u.k ? b+'|'+u.k : b; }
function careUnitSug(c, u){ var sd = itemSurgDate(c, u.it), dys = pcDays(u.x); return (sd && dys.length) ? ymdAdd(sd, dys[Math.min(u.k||0, dys.length-1)]) : ''; }
function careUnitLabel(x){ return (x.mgmt||x.name)+(x.place==='KR' ? '（在韩国）' : ''); }
/* 术后管理［预约时间］：按日期建立 / 并入子案件（同一天同一地点合成一个），预约来源 = 术后预约；reuseId = 取消本次后退回的那一行 */
function coreCareBook(c, itemName, pcIdx, date, time, place, reuseId, by, opt){
  var it = (c.procedureItems||[]).filter(function(x){ return x.name===itemName; })[0], x = it && (it.postcare||[])[pcIdx]; if(!it || !x || !date || !c.krBalancePaid) return false;
  var inn = place==='IN' && x.place==='either', content = inn ? (x.mgmt||x.name)+(x.innName ? '（回印尼做：'+x.innName+'）' : '（回印尼做）') : (x.mgmt||x.name)+(x.mgmt && x.mgmt!==x.name ? '（'+x.name+'，在韩国）' : '（在韩国）'), s;
  if(reuseId){ s = (c.subItems||[]).filter(function(r){ return r.id===reuseId; })[0]; if(!s) return false; s.skipped = false; s.kept = false; s.arrived = false; s.simDay = false; s.date = date; s.time = inn ? '' : time; s.place = inn ? 'IN' : 'KR'; s.content = content; }
  else { s = coreSubAdd(c, {kind:'术后管理记录', date:date, time:inn ? '' : time, content:content, place:inn ? 'IN' : 'KR', projectName:itemName, pcb:true, silent:true, salt:'u'+Math.floor(Math.random()*1e4)}, by); if(!s) return false; }
  s.postponed = false; s.postponedFrom = ''; if(c.visitEnds) delete c.visitEnds[subCaseKey(s)];
  s.src = 'care'; if(inn){ s.innName = x.innName||''; s.careItem = itemName; s.suggest = date; }
  if(!inn && opt && opt.dirOp){ s.dirOp = true; s.director = opt.dir || c.director; s.dirMin = opt.min || 30; s.extendMin = opt.ext || 0; } else { s.dirOp = false; s.extendMin = 0; } /* CMD-1020-05：院长操作 */
  c.pcBooked = careUnits(c).unbooked.length===0 && careUnits(c).rows.every(function(r){ return !r.s.skipped; });
  subCaseNos(c); logCaseEvent(c, by, '术后管理预约：'+buyName(itemName)+' · '+(x.name||x.mgmt)+'，'+date+(inn ? '（回印尼做，建议日期）' : ' '+time), '术后管理'); return true;
}
/* ===== CMD-1020-08：IN 备注记录 + KR 已读 =====
   c.inNotes = [{id, text, by, at(UTC), readAt, readBy}]；c.recInNote 保持 = 全部备注拼起来（打印 / 其他地方沿用）；IN 新增 → KR 收通知；KR 结算前（尾款 / 在韩加项）必须读过 */
function coreAddInNote(c, text, by){
  text = String(text||'').trim(); if(!text) return false;
  (c.inNotes = c.inNotes || []).push({id:'n'+Date.now()+Math.floor(Math.random()*1000), text:text, by:by, at:nowFullDt(), readAt:'', readBy:''});
  c.recInNote = c.inNotes.map(function(n){ return n.text; }).join('\n');
  logCaseEvent(c, by, '增加备注：'+(text.length>40 ? text.slice(0, 40)+'…' : text), '赴韩施术');
  try{ pushKrNotif(caseKrHospital(c), 'IN 备注：'+c.name+'（'+(c.caseNo||'')+'）'+(text.length>30 ? text.slice(0, 30)+'…' : text), {caseId:c.id, clinicId:c.clinicId||CURRENT_CLINIC_ID, kind:'innote', level:'action'}); }catch(e){}
  return true;
}
function krUnreadNotes(c){ return (c.inNotes||[]).filter(function(n){ return !n.readAt; }); }
function coreNoteRead(c, id, by){
  var n = (c.inNotes||[]).filter(function(x){ return x.id===id; })[0]; if(!n || n.readAt) return false;
  n.readAt = nowFullDt(); n.readBy = by; logCaseEvent(c, by, '已读 IN 备注：'+(n.text.length>30 ? n.text.slice(0, 30)+'…' : n.text), '赴韩施术'); return true;
}
function inNotesAreaHtml(c){ return notesCompactHtml(c, 'IN'); } /* CMD-1021-14 五：和 KR 同一张备注卡（最新 3 条 + 固定高度 + 两个按钮开 Modal） */
/* ===== CMD-1021-14 五：备注卡（IN / KR 共用）：最新的在最上面只显示 3 条（每条最多 2 行 + 省略号）、高度固定（= 3 条 + 底部按钮行）；底部［增加备注］［查看全部（N）］（≤ 3 条不显示查看全部）都开 DS Modal ===== */
function notesCompactHtml(c, role, title){
  /* CMD-1025-01 十：没有备注 = 整张卡只剩一行「备注 ……［增加备注］」；有备注每多一则长高一行，最多露出 3 则，超过在卡里滚动；［查看全部］照旧 */
  var n = caseNotesAll(c).length, can = role==='IN' ? true : (typeof krCanMemo==='function' && krCanMemo());
  var btns = '<div class="notes-btns">'+(can ? '<button class="btn-outline" style="padding:5px 16px;font-size:12px;" onclick="notesAddOpen(\''+role+'\')">增加备注</button>' : '')+(n>3 ? '<button class="btn-outline" style="padding:5px 16px;font-size:12px;" onclick="notesAllOpen(\''+role+'\')">查看全部（'+n+'）</button>' : '')+'</div>';
  return '<div class="notes-compact"><div class="notes-head"><div class="notes-title">'+(title || '备注')+'</div>'+btns+'</div>'+(n ? '<div class="notes-list">'+caseNotesListHtml(c, role, {clamp:true})+'</div>' : '')+'</div>';
}
var NOTES_ALL_ROLE = '';
function notesCtxCase(role){ if(role==='KR'){ var r = (typeof krFindCase==='function' && typeof KR_CASE!=='undefined') ? krFindCase(KR_CASE.clinicId, KR_CASE.id) : null; return r ? r.c : null; } return getCurrentCase(); }
function notesOverlay(){ var ov = document.getElementById('notes-overlay'); if(!ov){ ov = document.createElement('div'); ov.id = 'notes-overlay'; ov.className = 'modal-overlay'; ov.style.zIndex = 100002; document.body.appendChild(ov); } return ov; }
function notesClose(){ var ov = document.getElementById('notes-overlay'); if(ov) ov.classList.remove('open'); NOTES_ALL_ROLE = ''; }
function notesAddOpen(role){
  var c = notesCtxCase(role); if(!c) return; if(role==='KR' && !(typeof krCanMemo==='function' && krCanMemo())) return;
  var ov = notesOverlay(); NOTES_ALL_ROLE = '';
  ov.innerHTML = '<div class="modal-box" style="width:520px;max-width:94vw;"><div style="font-size:16px;font-weight:700;margin-bottom:10px;">增加备注 · '+aEscC(c.name)+'</div><textarea id="notes-add-text" rows="5" placeholder="备注内容（整体备注，不属于任何一次到院）" style="width:100%;padding:10px;border:1px solid var(--border);border-radius:8px;box-sizing:border-box;font-size:13px;font-family:inherit;"></textarea><div id="notes-add-err" style="font-size:12px;color:#B3261E;min-height:18px;margin-top:4px;"></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:8px;"><button class="btn-ghost" onclick="notesClose()">取消</button><button class="btn-primary" onclick="notesAddSave(\''+role+'\')">保存</button></div></div>';
  ov.classList.add('open'); var t = document.getElementById('notes-add-text'); if(t) t.focus();
}
function notesAddSave(role){
  var el = document.getElementById('notes-add-text'), err = document.getElementById('notes-add-err'); if(!el) return; var v = String(el.value||'').trim();
  if(!v){ if(err) err.textContent = '请填写备注内容'; return; }
  notesClose();
  if(role==='KR'){ krMut(function(c){ return coreAddProgressMemo(c, v, ME_NAME, ''); }); }
  else { var c = getCurrentCase(); if(c){ coreAddInNote(c, v, actingName()); renderCaseBody(c); } }
}
function notesAllOpen(role){
  var c = notesCtxCase(role); if(!c) return; var ov = notesOverlay(); NOTES_ALL_ROLE = role;
  var n = caseNotesAll(c).length;
  ov.innerHTML = '<div class="modal-box" style="width:620px;max-width:94vw;display:flex;flex-direction:column;max-height:84vh;"><div style="font-size:16px;font-weight:700;margin-bottom:6px;">全部备注（'+n+'）· '+aEscC(c.name)+'</div><div style="flex:1;overflow-y:auto;min-height:120px;">'+caseNotesListHtml(c, role)+'</div><div style="display:flex;justify-content:flex-end;margin-top:12px;"><button class="btn-primary" onclick="notesClose()">关闭</button></div></div>';
  ov.classList.add('open');
}
function notesAllRefresh(){ if(NOTES_ALL_ROLE && document.getElementById('notes-overlay') && document.getElementById('notes-overlay').classList.contains('open')) notesAllOpen(NOTES_ALL_ROLE); }
var IN_NOTE_OPEN = false;
