      var times = booked.map(function(s){ return md(s.date)+(s.time ? ' '+e(s.time) : ''); });
      if(holdItemTodayPicked(c, it)>0) times.unshift(md(mainVisitDay(c))+(ks.confirmedTime ? ' '+e(ks.confirmedTime) : ''));
