function contToggleType(){} /* CMD-1026-07：服务内容在第一个对话框勾，第二个弹窗不能改（保留空函数，旧调用不报错） */
function contToggleCare(){} /* CMD-1026-05：今日预约管理只看不能改（保留空函数，旧调用不报错） */
